//! # vld-utoipa — Bridge between `vld` and `utoipa`
//!
//! This crate lets you use `vld` validation schemas as the **single source of truth**
//! for both runtime validation and OpenAPI documentation generated by
//! [utoipa](https://docs.rs/utoipa).
//!
//! Instead of duplicating schema definitions with `#[derive(ToSchema)]` **and**
//! `vld::schema!`, you define validation rules once in `vld` and get `utoipa`
//! compatibility for free.
//!
//! # Quick Start
//!
//! ```rust
//! use vld::prelude::*;
//! use vld_utoipa::impl_to_schema;
//!
//! // 1. Define your validated struct as usual
//! vld::schema! {
//!     #[derive(Debug)]
//!     pub struct User {
//!         pub name: String => vld::string().min(2).max(50),
//!         pub email: String => vld::string().email(),
//!     }
//! }
//!
//! // 2. Bridge to utoipa — one line
//! impl_to_schema!(User);
//!
//! // Now `User` implements `utoipa::ToSchema` and can be used in
//! // `#[utoipa::path]` annotations.
//! ```
//!
//! # Converting arbitrary JSON Schema
//!
//! ```rust
//! use vld_utoipa::json_schema_to_schema;
//!
//! let json_schema = serde_json::json!({
//!     "type": "object",
//!     "required": ["name"],
//!     "properties": {
//!         "name": { "type": "string", "minLength": 1 }
//!     }
//! });
//!
//! let utoipa_schema = json_schema_to_schema(&json_schema);
//! // Returns `utoipa::openapi::RefOr<utoipa::openapi::schema::Schema>`
//! ```

#[cfg(all(feature = "utoipa-5", feature = "utoipa-6"))]
compile_error!("Enable exactly one utoipa version feature: `utoipa-5` or `utoipa-6`.");
#[cfg(not(any(feature = "utoipa-5", feature = "utoipa-6")))]
compile_error!("Enable one utoipa version feature: `utoipa-5` or `utoipa-6`.");

#[cfg(feature = "utoipa-5")]
pub use utoipa;
#[cfg(feature = "utoipa-6")]
pub use utoipa6 as utoipa;

use serde_json::Value;
use utoipa::openapi::extensions::Extensions;
use utoipa::openapi::path::{Parameter, ParameterBuilder, ParameterIn};
use utoipa::openapi::schema::{
    AdditionalProperties, AllOf, AnyOf, Array, ArrayItems, Object, OneOf, Schema, SchemaFormat,
    SchemaType, Type,
};
use utoipa::openapi::{Ref, RefOr, Required};

type Map = serde_json::Map<String, Value>;

/// Convert a `serde_json::Value` (JSON Schema) produced by `vld` into a
/// `utoipa::openapi::RefOr<Schema>`.
///
/// This is the core conversion function. It handles:
/// - Primitive types: `string`, `number`, `integer`, `boolean`, `null`
/// - Type arrays such as `["string", "null"]`; a missing `type` means "any value"
/// - Objects with `properties`, `required`, `additionalProperties`,
///   `minProperties`, `maxProperties`
/// - Arrays with `items`, `minItems`, `maxItems`, `uniqueItems`
/// - `oneOf`, `anyOf`, `allOf` composites
/// - `enum` and `const` values
/// - Numeric constraints: `minimum`, `maximum`, `exclusiveMinimum`, `exclusiveMaximum`, `multipleOf`
/// - String constraints: `minLength`, `maxLength`, `pattern`
/// - `format`, `title`, `description`, `default`, `example` — on every schema kind
///   (`anyOf` has no `title` in utoipa)
/// - `allOf` next to other keywords: those keywords become the first `allOf` member
/// - `not: {}` / `false` (`vld::never()`) stay "nothing is valid" (`{"not": {}}`)
/// - `x-*` extensions and keywords utoipa has no field for (`contains`,
///   `minContains`, `maxContains`, `propertyNames`, `formatMinimum`,
///   `formatMaximum`, `not`) are kept verbatim as schema extensions
/// - `$ref` references: a sibling `description` stays on the ref; `title`,
///   `default` or `example` wrap the ref in a single-item `allOf`
///
/// # Example
///
/// ```rust
/// use vld_utoipa::json_schema_to_schema;
///
/// let schema = json_schema_to_schema(&serde_json::json!({"type": "string", "format": "email"}));
/// ```
pub fn json_schema_to_schema(value: &Value) -> RefOr<Schema> {
    let map = match value {
        Value::Object(map) => map,
        // `false`: nothing is valid.
        Value::Bool(false) => return never(),
        // `true` / other non-object schemas: accept any value.
        _ => return RefOr::T(Schema::Object(Object::with_type(SchemaType::AnyValue))),
    };
    // `not` (e.g. `vld::never()`'s `{"not": {}}`) is kept as an extension below.
    let title = str_of(map, "title");
    let description = str_of(map, "description");
    let default = map.get("default").cloned();
    let example = map.get("example").cloned();
    let extensions = extensions_of(map);

    // Sets the shared annotation fields on any utoipa schema struct.
    macro_rules! annotate {
        ($target:expr $(, $title:ident)?) => {{
            let mut t = $target;
            $( t.$title = title.clone(); )?
            t.description = description.clone();
            t.default = default.clone();
            t.example = example.clone();
            t.extensions = extensions.clone();
            t
        }};
    }

    if let Some(Value::String(path)) = map.get("$ref") {
        let mut reference = Ref::new(path.clone());
        if title.is_none() && default.is_none() && example.is_none() {
            reference.description = description.unwrap_or_default();
            return RefOr::Ref(reference);
        }
        let mut all_of = annotate!(AllOf::new(), title);
        all_of.items = vec![RefOr::Ref(reference)];
        return RefOr::T(Schema::AllOf(all_of));
    }

    if let Some(items) = composite_items(map, "oneOf") {
        let mut one_of = annotate!(OneOf::new(), title);
        one_of.items = items;
        return RefOr::T(Schema::OneOf(one_of));
    }
    if let Some(items) = composite_items(map, "anyOf") {
        let mut any_of = annotate!(AnyOf::new());
        any_of.items = items;
        return RefOr::T(Schema::AnyOf(any_of));
    }
    if let Some(mut items) = composite_items(map, "allOf") {
        // Core puts extra patterns / formats / multipleOf into `allOf` next to
        // `type`: keep that typed base as the first `allOf` member.
        let mut base = map.clone();
        base.remove("allOf");
        base.retain(|k, _| !ANNOTATIONS.contains(&k.as_str()) && !is_extension(k));
        if !base.is_empty() {
            items.insert(0, json_schema_to_schema(&Value::Object(base)));
        }
        let mut all_of = annotate!(AllOf::new(), title);
        all_of.items = items;
        return RefOr::T(Schema::AllOf(all_of));
    }

    let types: Vec<Type> = match map.get("type") {
        Some(Value::String(t)) => type_of(t).into_iter().collect(),
        Some(Value::Array(ts)) => ts
            .iter()
            .filter_map(|t| t.as_str().and_then(type_of))
            .collect(),
        _ => Vec::new(),
    };
    let schema_type = match types.as_slice() {
        [] => SchemaType::AnyValue,
        [t] => SchemaType::Type(t.clone()),
        ts => SchemaType::Array(ts.to_vec()),
    };

    if types.contains(&Type::Array) {
        let items = map
            .get("items")
            .map(json_schema_to_schema)
            .unwrap_or_else(|| RefOr::T(Schema::Object(Object::with_type(SchemaType::AnyValue))));
        let mut arr = annotate!(Array::new(items), title);
        arr.schema_type = schema_type;
        // Tuples: `prefixItems` + `items: false`.
        if let Some(Value::Array(prefix)) = map.get("prefixItems") {
            arr.prefix_items = prefix.iter().map(ref_or_to_schema).collect();
        }
        if map.get("items") == Some(&Value::Bool(false)) {
            arr.items = ArrayItems::False;
        }
        arr.min_items = usize_of(map, "minItems");
        arr.max_items = usize_of(map, "maxItems");
        arr.unique_items = map.get("uniqueItems") == Some(&Value::Bool(true));
        return RefOr::T(Schema::Array(arr));
    }

    let mut obj = annotate!(Object::with_type(schema_type), title);
    obj.format = str_of(map, "format").map(SchemaFormat::Custom);
    obj.enum_values = match (map.get("enum"), map.get("const")) {
        (Some(Value::Array(vals)), _) => Some(vals.clone()),
        (_, Some(c)) => Some(vec![c.clone()]),
        _ => None,
    };
    obj.pattern = str_of(map, "pattern");
    obj.min_length = usize_of(map, "minLength");
    obj.max_length = usize_of(map, "maxLength");
    obj.minimum = num_of(map, "minimum");
    obj.maximum = num_of(map, "maximum");
    obj.exclusive_minimum = num_of(map, "exclusiveMinimum");
    obj.exclusive_maximum = num_of(map, "exclusiveMaximum");
    obj.multiple_of = num_of(map, "multipleOf");
    if let Some(Value::Object(props)) = map.get("properties") {
        for (key, val) in props {
            obj.properties
                .insert(key.clone(), json_schema_to_schema(val));
        }
    }
    if let Some(Value::Array(req)) = map.get("required") {
        obj.required = req
            .iter()
            .filter_map(|v| v.as_str().map(String::from))
            .collect();
    }
    obj.additional_properties = match map.get("additionalProperties") {
        Some(Value::Bool(b)) => Some(Box::new(AdditionalProperties::FreeForm(*b))),
        Some(v @ Value::Object(_)) => Some(Box::new(AdditionalProperties::RefOr(
            json_schema_to_schema(v),
        ))),
        _ => None,
    };
    obj.min_properties = usize_of(map, "minProperties");
    obj.max_properties = usize_of(map, "maxProperties");
    RefOr::T(Schema::Object(obj))
}

/// Keys carried by `annotate!` on every schema kind.
const ANNOTATIONS: &[&str] = &["title", "description", "default", "example"];

/// JSON Schema keywords utoipa has no field for; they are kept verbatim as
/// schema extensions (serialized next to the other keywords).
const PASSTHROUGH: &[&str] = &[
    "contains",
    "minContains",
    "maxContains",
    "propertyNames",
    "formatMinimum",
    "formatMaximum",
    "not",
];

fn is_extension(k: &str) -> bool {
    k.starts_with("x-") || PASSTHROUGH.contains(&k)
}

/// `x-*` keys and [`PASSTHROUGH`] keywords as utoipa extensions.
fn extensions_of(map: &Map) -> Option<Extensions> {
    let ext: Extensions = map
        .iter()
        .filter(|(k, _)| is_extension(k))
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    (!ext.is_empty()).then_some(ext)
}

/// `{"not": {}}`: a schema nothing satisfies.
fn never() -> RefOr<Schema> {
    let mut obj = Object::with_type(SchemaType::AnyValue);
    obj.extensions = Some([("not", serde_json::json!({}))].into_iter().collect());
    RefOr::T(Schema::Object(obj))
}

/// `prefixItems` holds plain schemas: a `$ref` becomes `allOf: [$ref]`.
fn ref_or_to_schema(v: &Value) -> Schema {
    match json_schema_to_schema(v) {
        RefOr::T(s) => s,
        r @ RefOr::Ref(_) => {
            let mut all_of = AllOf::new();
            all_of.items = vec![r];
            Schema::AllOf(all_of)
        }
    }
}

fn composite_items(map: &Map, key: &str) -> Option<Vec<RefOr<Schema>>> {
    map.get(key)
        .and_then(Value::as_array)
        .map(|items| items.iter().map(json_schema_to_schema).collect())
}

fn type_of(t: &str) -> Option<Type> {
    Some(match t {
        "string" => Type::String,
        "number" => Type::Number,
        "integer" => Type::Integer,
        "boolean" => Type::Boolean,
        "null" => Type::Null,
        "object" => Type::Object,
        "array" => Type::Array,
        _ => return None,
    })
}

fn str_of(map: &Map, key: &str) -> Option<String> {
    map.get(key).and_then(Value::as_str).map(str::to_owned)
}

fn usize_of(map: &Map, key: &str) -> Option<usize> {
    map.get(key).and_then(Value::as_u64).map(|n| n as usize)
}

fn num_of(map: &Map, key: &str) -> Option<utoipa::Number> {
    let n = map.get(key)?;
    Some(match (n.as_i64(), n.as_f64()) {
        (Some(i), _) if isize::try_from(i).is_ok() => utoipa::Number::Int(i as isize),
        // Above i64 (`u64` bounds): keep the exact integer.
        (None, _) if n.as_u64().is_some_and(|u| usize::try_from(u).is_ok()) => {
            utoipa::Number::UInt(n.as_u64().unwrap() as usize)
        }
        (_, Some(f)) if f.fract() == 0.0 && f.abs() < isize::MAX as f64 => {
            utoipa::Number::Int(f as isize)
        }
        (_, Some(f)) => utoipa::Number::Float(f),
        _ => return None,
    })
}

/// If `schema` is an optional/nullable union (`oneOf`/`anyOf` of one schema plus
/// `{"type": "null"}`), return the non-null branch with the union's own
/// annotations (`description`, `default`, `title`, …) merged in.
fn unwrap_nullable_schema(schema: &Value) -> Value {
    let Some(map) = schema.as_object() else {
        return schema.clone();
    };
    for key in ["oneOf", "anyOf"] {
        let Some(items) = map.get(key).and_then(Value::as_array) else {
            continue;
        };
        let is_null = |v: &&Value| v.get("type").and_then(Value::as_str) == Some("null");
        let rest: Vec<&Value> = items.iter().filter(|v| !is_null(v)).collect();
        if let [inner] = rest.as_slice() {
            if rest.len() < items.len() {
                let mut inner = (*inner).clone();
                if let Some(obj) = inner.as_object_mut() {
                    for (k, v) in map.iter().filter(|(k, _)| *k != key) {
                        obj.entry(k.clone()).or_insert_with(|| v.clone());
                    }
                }
                return inner;
            }
        }
    }
    schema.clone()
}

/// Convert a vld object `json_schema()` into OpenAPI path/query parameters.
///
/// Each property becomes a [`Parameter`] with per-field validation constraints
/// preserved from the vld schema (e.g. `minLength`, `minimum`).
pub fn json_schema_to_params(value: &Value, parameter_in: ParameterIn) -> Vec<Parameter> {
    let Some(map) = value.as_object() else {
        return Vec::new();
    };

    let properties = map
        .get("properties")
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();

    let required_fields: Vec<&str> = map
        .get("required")
        .and_then(Value::as_array)
        .map(|arr| arr.iter().filter_map(|v| v.as_str()).collect())
        .unwrap_or_default();

    properties
        .into_iter()
        .map(|(name, field_schema)| {
            // `required` array is the source of truth (optional/nullish/default omit
            // the key; nullable keeps it). Do not infer requiredness from oneOf+null —
            // both optional and nullable emit that shape.
            let schema_value = unwrap_nullable_schema(&field_schema);
            let required = if required_fields.contains(&name.as_str()) {
                Required::True
            } else {
                Required::False
            };

            let description = schema_value
                .get("description")
                .and_then(Value::as_str)
                .map(str::to_owned);

            ParameterBuilder::new()
                .name(name)
                .parameter_in(parameter_in.clone())
                .required(required)
                .description(description)
                .schema(Some(json_schema_to_schema(&schema_value)))
                .build()
        })
        .collect()
}

/// Map a parameter location hint from [`vld::openapi::OpenApiParameterIn`] to utoipa.
pub fn parameter_in_from_str(s: &str) -> Option<ParameterIn> {
    match s {
        "query" => Some(ParameterIn::Query),
        "path" => Some(ParameterIn::Path),
        "header" => Some(ParameterIn::Header),
        "cookie" => Some(ParameterIn::Cookie),
        _ => None,
    }
}

#[doc(hidden)]
pub fn resolve_parameter_in_with_override<T: vld::openapi::OpenApiParameterIn>(
    parameter_in_provider: impl FnOnce() -> Option<ParameterIn>,
    override_hint: Option<ParameterIn>,
) -> Option<ParameterIn> {
    parameter_in_provider()
        .or(override_hint)
        .or_else(|| T::parameter_in().and_then(parameter_in_from_str))
}

#[doc(hidden)]
pub fn resolve_parameter_in<T: vld::openapi::OpenApiParameterIn>(
    parameter_in_provider: impl FnOnce() -> Option<ParameterIn>,
) -> Option<ParameterIn> {
    resolve_parameter_in_with_override::<T>(parameter_in_provider, None)
}

#[doc(hidden)]
#[macro_export]
macro_rules! __impl_to_schema {
    (
        $ty:ty,
        name: { $($name_method:tt)* },
        param_in: $param_in_override:expr $(,)?
    ) => {
        impl $crate::utoipa::PartialSchema for $ty {
            fn schema() -> $crate::utoipa::openapi::RefOr<$crate::utoipa::openapi::schema::Schema> {
                $crate::json_schema_to_schema(&<$ty>::json_schema())
            }
        }

        impl $crate::utoipa::ToSchema for $ty {
            $($name_method)*

            fn schemas(
                schemas: &mut ::std::vec::Vec<(
                    ::std::string::String,
                    $crate::utoipa::openapi::RefOr<$crate::utoipa::openapi::schema::Schema>,
                )>,
            ) {
                // Inherent `__vld_nested_schemas` (from `vld::schema!` / derive) wins
                // over this trait fallback in `<T>::f()` path resolution.
                #[allow(unused_imports)]
                use $crate::__VldNestedSchemasFallback as _;
                for (name, schema_fn) in <$ty>::__vld_nested_schemas() {
                    let json = schema_fn();
                    schemas.push((name.to_string(), $crate::json_schema_to_schema(&json)));
                }
            }
        }

        impl $crate::utoipa::IntoParams for $ty {
            fn into_params(
                parameter_in_provider: impl Fn() -> Option<$crate::utoipa::openapi::path::ParameterIn>,
            ) -> ::std::vec::Vec<$crate::utoipa::openapi::path::Parameter> {
                let Some(parameter_in) = $crate::resolve_parameter_in_with_override::<$ty>(
                    parameter_in_provider,
                    $param_in_override,
                ) else {
                    return ::std::vec::Vec::new();
                };
                $crate::json_schema_to_params(&<$ty>::json_schema(), parameter_in)
            }
        }
    };
}

/// Bridge a vld type to utoipa (`ToSchema` + `IntoParams` when applicable).
///
/// Works for **request/response bodies** and for **query/path parameters** — the same
/// one-liner as with `#[derive(Validate)]`. Mark parameter structs with utoipa's
/// `#[into_params(parameter_in = Query)]` (or `Path`, `Header`, `Cookie`) on the struct.
///
/// # Body
///
/// ```rust
/// use vld::prelude::*;
/// use vld_utoipa::impl_to_schema;
///
/// vld::schema! {
///     #[derive(Debug)]
///     pub struct CreateUser {
///         pub name: String => vld::string().min(2).max(100),
///         pub email: String => vld::string().email(),
///     }
/// }
///
/// impl_to_schema!(CreateUser);
/// // #[utoipa::path(post, path = "/users", request_body = CreateUser)]
/// ```
///
/// # Query / path parameters
///
/// ```rust
/// use vld::prelude::*;
/// use vld_utoipa::impl_to_schema;
///
/// vld::schema! {
///     #[derive(Debug)]
///     #[into_params(parameter_in = Query)]
///     pub struct SearchQuery {
///         pub q: String => vld::string().min(1).max(200),
///     }
/// }
///
/// impl_to_schema!(SearchQuery);
/// // #[utoipa::path(get, path = "/search", params(SearchQuery))]
/// ```
///
/// Custom OpenAPI component name:
///
/// ```rust
/// # use vld::prelude::*;
/// # use vld_utoipa::impl_to_schema;
/// # vld::schema! {
/// #     #[derive(Debug)]
/// #     pub struct Req { pub x: String => vld::string() }
/// # }
/// impl_to_schema!(Req, "CreateUserRequest");
/// ```
#[macro_export]
macro_rules! impl_to_schema {
    ($ty:ty) => {
        $crate::__impl_to_schema!($ty, name: {}, param_in: None);
    };
    ($ty:ty, $name:literal) => {
        $crate::__impl_to_schema!(
            $ty,
            name: {
                fn name() -> ::std::borrow::Cow<'static, str> {
                    ::std::borrow::Cow::Borrowed($name)
                }
            },
            param_in: None,
        );
    };
    ($ty:ty, query) => {
        $crate::__impl_to_schema_legacy!($ty, Query);
    };
    ($ty:ty, path) => {
        $crate::__impl_to_schema_legacy!($ty, Path);
    };
    ($ty:ty, header) => {
        $crate::__impl_to_schema_legacy!($ty, Header);
    };
    ($ty:ty, cookie) => {
        $crate::__impl_to_schema_legacy!($ty, Cookie);
    };
}

/// Deprecated alias for [`impl_to_schema!`].
#[macro_export]
#[deprecated(note = "use #[into_params(parameter_in = ...)] on the struct and impl_to_schema!(T)")]
macro_rules! impl_into_params {
    ($ty:ty) => {
        $crate::impl_to_schema!($ty);
    };
    ($ty:ty, $name:literal) => {
        $crate::impl_to_schema!($ty, $name);
    };
    ($ty:ty, $loc:ident) => {
        $crate::__impl_to_schema_legacy!($ty, $loc);
    };
}

/// Deprecated — use `#[into_params(parameter_in = Query)]` + [`impl_to_schema!`].
#[macro_export]
#[deprecated(
    note = "use #[into_params(parameter_in = Query)] on the struct and impl_to_schema!(T)"
)]
macro_rules! impl_to_schema_query {
    ($ty:ty) => {
        $crate::__impl_to_schema_legacy!($ty, Query);
    };
}

/// Deprecated — use `#[into_params(parameter_in = Path)]` + [`impl_to_schema!`].
#[macro_export]
#[deprecated(note = "use #[into_params(parameter_in = Path)] on the struct and impl_to_schema!(T)")]
macro_rules! impl_to_schema_path {
    ($ty:ty) => {
        $crate::__impl_to_schema_legacy!($ty, Path);
    };
}

/// Legacy explicit parameter location (`Query`, `Path`, `Header`, `Cookie`).
#[doc(hidden)]
#[macro_export]
#[deprecated(note = "use #[into_params(parameter_in = ...)] on the struct and impl_to_schema!(T)")]
macro_rules! __impl_to_schema_legacy {
    ($ty:ty, $loc:ident) => {
        $crate::__impl_to_schema!(
            $ty,
            name: {},
            param_in: Some($crate::utoipa::openapi::path::ParameterIn::$loc),
        );
    };
}

#[doc(hidden)]
pub trait __VldNestedSchemasFallback {
    fn __vld_nested_schemas() -> Vec<vld::openapi::NestedSchemaEntry> {
        Vec::new()
    }
}

impl<T: ?Sized> __VldNestedSchemasFallback for T {}

/// Prelude module — import everything you need.
pub mod prelude {
    #[allow(deprecated)]
    pub use crate::impl_into_params;
    pub use crate::impl_to_schema;
    #[allow(deprecated)]
    pub use crate::impl_to_schema_path;
    #[allow(deprecated)]
    pub use crate::impl_to_schema_query;
    pub use crate::json_schema_to_params;
    pub use crate::json_schema_to_schema;
    pub use vld::prelude::*;
}
